export function resolveLegacyPlanSocketName(
	legacyOrFoxholeKey: string,
	legacySocketId: string | number,
	options: { legacyKey?: string | null; foxholeKey?: string | null; } = {},
): string | null {
	const id = String(legacySocketId);
	const candidates = [
		options.legacyKey,
		legacyOrFoxholeKey,
		options.foxholeKey,
	]
		.map(value => String(value ?? '').trim())
		.filter(Boolean);
	for (const key of candidates) {
		const mapping = LEGACY_PLAN_SOCKET_ID_MAP[key];
		if (mapping?.[id]) {
			return mapping[id];
		}
	}
	return null;
}

/** Resolve the serialized legacy socket id for an already-resolved Nixie socket name. */
export function resolveLegacyPlanSocketId(
	legacyOrFoxholeKey: string,
	socketName: string,
	options: { legacyKey?: string | null; foxholeKey?: string | null; } = {},
): string | null {
	const normalizedSocketName = String(socketName ?? '').trim();
	if (!normalizedSocketName) {
		return null;
	}
	const candidates = [
		options.legacyKey,
		legacyOrFoxholeKey,
		options.foxholeKey,
	]
		.map(value => String(value ?? '').trim())
		.filter(Boolean);
	for (const key of candidates) {
		const mapping = LEGACY_PLAN_SOCKET_ID_MAP[key];
		const match = Object.entries(mapping ?? {}).find(([, mappedSocketName]) => mappedSocketName === normalizedSocketName);
		if (match) {
			return match[0];
		}
	}
	return null;
}

export function resolveLegacyPlanSocketMatchMeta(legacyOrFoxholeKey: string): LegacyPlanSocketMatchEntry | null {
	return LEGACY_PLAN_SOCKET_MATCH_META[String(legacyOrFoxholeKey ?? '').trim()] ?? null;
}
